    float n2 = fbm(vec2(flow * 0.022 + 5.0, py / halfWidth * 2.3 - time * 2.0));
    float n3 = fbm(vec2(flow * 0.035 + 9.0, py / halfWidth * 3.0 + time * 1.7));
    float sideN = fbm(vec2(flow * 0.011 + (py >= 0.0 ? 17.0 : 41.0), time * 1.3));
