    float y = abs(py + (n2 - 0.5) * halfWidth * 0.45) + (n3 - 0.5) * halfWidth * 0.35;
    float body = 1.0 - smoothstep(width * 0.5, width, y);
    float inner = 1.0 - smoothstep(0.0, width * 0.7, y);
    float streak = smoothstep(0.42, 0.85, fbm(vec2(flow * 0.013 + 11.0, py / halfWidth * 2.2)));
